package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Objects;

/** The value a dated setting of a sheet takes from a date on (the floor, the late percent, the terms
 *  of the sheet and of each grade, the clerk limit, the cap); in force until a later from-date of the
 *  same key. A null value is blank: no limit, no cap. */
@Entity
@Table(name = "setting_value")
@IdClass(SettingValue.Key.class)
public class SettingValue {

    /** The key of a setting value: its sheet, setting and from-date. */
    public static class Key implements Serializable {
        private String sheetId;
        private String key;
        private LocalDate from;

        protected Key() {
        }

        public Key(String sheetId, String key, LocalDate from) {
            this.sheetId = sheetId;
            this.key = key;
            this.from = from;
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof Key k && Objects.equals(sheetId, k.sheetId) && Objects.equals(key, k.key)
                    && Objects.equals(from, k.from);
        }

        @Override
        public int hashCode() {
            return Objects.hash(sheetId, key, from);
        }
    }

    @Id
    @Column(name = "sheet_id")
    private String sheetId;

    @Id
    @Column(name = "setting_key")
    private String key;

    @Id
    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "setting", precision = 14, scale = 2)
    private BigDecimal value;

    protected SettingValue() {
    }

    public SettingValue(String sheetId, String key, LocalDate from, BigDecimal value) {
        this.sheetId = sheetId;
        this.key = key;
        this.from = from;
        this.value = value;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFrom() {
        return from;
    }

    public BigDecimal getValue() {
        return value;
    }

    public void setValue(BigDecimal value) {
        this.value = value;
    }
}
package net.officefloor.hq.app.role;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The roles user names have on a sheet: clerk (the default for any name) or steward. */
@Service
public class RoleService {

    private final SheetRoleRepository roles;
    private final SheetService sheets;
    private final Audit audit;

    public RoleService(SheetRoleRepository roles, SheetService sheets, Audit audit) {
        this.roles = roles;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The roles given on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> list(String sheetId) {
        return roles.findBySheetIdOrderByUserNameAsc(sheetId);
    }

    /** The role of a user name on the sheet: clerk unless it was given another. */
    @Transactional(readOnly = true)
    public String roleOf(String sheetId, String userName) {
        return roles.findBySheetIdAndUserName(sheetId, userName).map(SheetRole::getRole).orElse(SheetRole.CLERK);
    }

    /** Give a user name a role on the sheet, replacing the one it had. */
    @Transactional
    public synchronized SheetRole set(String sheetId, String user, String userName, String role) {
        sheets.load(sheetId, user);
        SheetRole given = roles.findBySheetIdAndUserName(sheetId, userName)
                .orElseGet(() -> new SheetRole(sheetId, userName, role));
        given.setRole(role);
        SheetRole saved = roles.saveAndFlush(given);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + user + " user=" + userName + " role=" + role);
        return saved;
    }
}

